 const {value,selectionStart:start,selectionEnd:end,selectionDirection:direction}=a;return ()=>{const x=main().querySelector(selector);if(!x)return;if(['stockSearch','partySearch'].includes(a.name))x.value=value;x.focus({preventScroll:true});try{x.setSelectionRange(start,end,direction||'none');}catch(_){}};
